const fs = require('fs');
const zlib = require('zlib');

// .docx is a ZIP file - parse it manually
const buf = fs.readFileSync('testbed/docs/customer_report.docx');

// Find local file headers (PK\x03\x04) and extract word/document.xml
let offset = 0;
while (offset < buf.length - 4) {
  if (buf[offset] === 0x50 && buf[offset+1] === 0x4b && buf[offset+2] === 0x03 && buf[offset+3] === 0x04) {
    const fnLen = buf.readUInt16LE(offset + 26);
    const extraLen = buf.readUInt16LE(offset + 28);
    const compMethod = buf.readUInt16LE(offset + 8);
    const compSize = buf.readUInt32LE(offset + 18);
    const uncompSize = buf.readUInt32LE(offset + 22);
    const fileName = buf.slice(offset + 30, offset + 30 + fnLen).toString('utf8');
    const dataStart = offset + 30 + fnLen + extraLen;

    if (fileName === 'word/document.xml') {
      const compData = buf.slice(dataStart, dataStart + compSize);
      let content;
      if (compMethod === 8) {
        content = zlib.inflateRawSync(compData).toString('utf8');
      } else {
        content = compData.toString('utf8');
      }
      // Extract text from XML
      const texts = [];
      const regex = /<w:t[^>]*>([^<]*)<\/w:t>/g;
      let m;
      while ((m = regex.exec(content)) !== null) {
        texts.push(m[1]);
      }
      // Also detect paragraph breaks
      const paragraphs = [];
      let current = '';
      // Split by paragraph markers
      const parts = content.split(/<\/w:p>/);
      for (const part of parts) {
        const pTexts = [];
        const r2 = /<w:t[^>]*>([^<]*)<\/w:t>/g;
        let m2;
        while ((m2 = r2.exec(part)) !== null) {
          pTexts.push(m2[1]);
        }
        if (pTexts.length > 0) {
          paragraphs.push(pTexts.join(''));
        }
      }
      console.log(paragraphs.join('\n'));
      process.exit(0);
    }
  }
  offset++;
}
console.error('word/document.xml not found');
"
